('6e6fde95-269a-4c54-9339-6118e43aacbe','{"val_partido":"4. ALTA RELEVANCIA","valoracion":"3.SEGUIR VIENDO","car_obs_ARQUERO":"Atento para cerrar a las espaldas de los defensores, buenos reflejos, atajador bajo palos, achica bien, buen salto, buen saque con el pie"}'),
