('a2933167-2ecf-446c-b65b-8be975501dee','{"val_partido":"4. ALTA RELEVANCIA","valoracion":"4.INTERESANTE","car_obs_MEDIOCENTRO":"CUENTA CON BUEN CRITERIO TACTICO TANTO PARA LA DISTRIBUCION DEL BALON COMO EN LA COBERTURA DE ESPACIOS."}'),
