('7392bba8-62a6-41db-a4df-95a28268d906','{"val_partido":"3. RELEVANCIA NORMAL","valoracion":"3.SEGUIR VIENDO","car_obs_MEDIOCENTRO":"Pivote de bastante entrega en cada pelota e intenso para ir a recuperar, por juventud perfil para seguir observando sin ser prioridad en el mercado."}'),
