('99caaa3b-69ff-4524-ad76-6e49482a3d6e','{"val_partido":"3. RELEVANCIA NORMAL","valoracion":"3.SEGUIR VIENDO","car_obs_CENTRAL":"Tiene buen manejo de balón y ofrece progresión desde el fondo a través de sus pases. Fuerte en el juego aéreo y sólido en duelos defensivos. No tiene mucha velocidad, más allá de su zancada. La transiciones parecen costarle por ese detalle"}'),
('99cefed5-686d-4bbd-bdb7-4db8345f5dc0','{"val_partido":"3. RELEVANCIA NORMAL","valoracion":"4.INTERESANTE"}'),
('9cd046e2-330d-431b-b6ad-9cf189b076e4','{"val_partido":"3. RELEVANCIA NORMAL","valoracion":"3.SEGUIR VIENDO","car_obs_MEDIOCENTRO":"Es un volante central de buen pie, distribuye bien el juego y escanea constantemente lo que ocurre a su alrededor. Mostró buenos dotes para filtrar pases en campo rival y progresar. Defensivamente está atento a las ayudas y muestra agresividad para chocar. Su laguna sería su velocidad y aceleración, ya que no se vio tan veloz en transiciones"}'),
('9d3c1385-2ca4-455c-8ae1-c2bb090ad69e','{"val_partido":"3. RELEVANCIA NORMAL","valoracion":"2.DESCARTAR"}'),
('9e773527-32af-411d-9b88-41eb513a4ed3','{"val_partido":"3. RELEVANCIA NORMAL","valoracion":"3.SEGUIR VIENDO"}'),
('a11a252b-5f3b-4c42-a93a-0cea659a4726','{"val_partido":"4. ALTA RELEVANCIA","valoracion":"3.SEGUIR VIENDO"}'),
('a7f0c384-15c2-417e-8c9b-41260397508e','{"val_partido":"3. RELEVANCIA NORMAL","valoracion":"3.SEGUIR VIENDO","car_obs_CENTRAL":"Central de buena velocidad y agilidad de movimientos para ser expeditivo en los duelos, pero algo exagerado en cometer faltas, por no tener tanto timming al anticipo. Será de seguir observando pero sin ser prioridad en el mercado."}'),
('a9c3f4e3-05ea-43e1-b36e-6bb414475b54','{"val_partido":"4. ALTA RELEVANCIA","valoracion":"5.FICHAR"}'),
('ad3844c1-7ad8-4190-a0c3-deaeb97390ef','{"val_partido":"3. RELEVANCIA NORMAL","valoracion":"2.DESCARTAR"}'),
('b1e59e86-60f9-4bc0-ac0c-ba479517aa1d','{"val_partido":"3. RELEVANCIA NORMAL","valoracion":"4.INTERESANTE","car_obs_ARQUERO":"Mostró buen juego de pies, progresando con pases ante presiones y sin ponerse nervioso cuando lo fueron a apretar. Veloz y atento para jugar como líbero y cortar transiciones, así como seguro para salir a descolgar centros laterales"}')
) as v(id, patch)
where r.id = v.id::uuid;

select count(*) as sin_val_partido from public.reports where coalesce(data->>'val_partido','') = '';
